import { WORDMARK } from './wordmark';

/**
 * The Empatherapy logo: the teacup symbol (Cassidy's symbol, as drawn for the film: public/brand/teacup.svg) beside
 * "Empatherapy" in the same script the honey writes in the film (components/layout/wordmark.js, generated by
 * film/golden-pause/wordmark-svg.js). The lettering takes the colour of the text around it (currentColor), so it
 * suits the light header and the dark footer, and high-contrast modes. Screen readers hear "Empatherapy".
 */
export default function Logo() {
  return (
    <span className="logo">
      <img className="logo__cup" src="/brand/teacup.svg" alt="" width="930" height="890" />
      <svg className="logo__script" viewBox={WORDMARK.viewBox} aria-hidden="true" focusable="false">
        <path d={WORDMARK.d} fill="currentColor" stroke="currentColor" strokeWidth={WORDMARK.strokeWidth} strokeLinejoin="round" strokeLinecap="round" />
      </svg>
      <span className="sr-only">Empatherapy</span>
    </span>
  );
}
